@use "../abstract" as *;

// 캔버스 전용 고정 레이어 (뷰포트에 고정, 낮은 z-index)
.canvas-container {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  pointer-events: none;

  .no-marquee {
    height: 100vh;
    &__viewport {
      height: 100%;
      @include flex-center();
    }
  }

  #canvas {
    display: block;
    width: 100%;
    height: 100%;
  }
}

// 스크롤 콘텐츠 레이어 (캔버스 위에서 스크롤)
.main-content {
  position: relative;

